create or replace function public.configurar_control_serial(p_product_id uuid,p_activo boolean) returns boolean language plpgsql security definer set search_path='public','private' as $$begin if not private.auth_is_admin() then raise exception 'Solo administradores';end if;if not p_activo and exists(select 1 from public.product_serials ps join public.product_variants pv on pv.id=ps.variant_id where pv.product_id=p_product_id and ps.estado in('disponible','en_transito','servicio')) then raise exception 'No se puede desactivar: existen unidades serializadas activas';end if;update public.products set control_serial=p_activo,updated_at=now() where id=p_product_id;if not found then raise exception 'Producto no encontrado';end if;return true;end$$;
grant execute on function public.configurar_control_serial(uuid,boolean) to authenticated;